import http from 'node:http';

const servidor = http.createServer((req, res) => {
  // 1. Só respondemos a GET nesta versão — o resto não dá para atender.
  if (req.method !== 'GET') {
    res.writeHead(405, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ erro: 'método não permitido' }));
    return; // return evita que o código abaixo rode para este pedido
  }

  // 2. A rota que existe: /api/ola.
  //    req.url guarda o caminho que veio no pedido.
  if (req.url === '/api/ola') {
    const dados = { mensagem: 'olá, mundo!' };
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(dados)); // objeto → texto JSON
    return;
  }

  // 3. Se chegou aqui, o caminho não existe no cardápio: 404.
  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ erro: 'rota não encontrada' }));
});

// 4. A porta 3000 é a "entrada" do balcão.
//    No navegador: http://localhost:3000/api/ola
servidor.listen(3000);
